// P1 防御：校验 webhook 静态密钥（?secret=）。失败直接丢弃。
const expected = (typeof $vars !== 'undefined' && $vars && $vars.webhook_secret) ? $vars.webhook_secret : '';
const q = ($input.item.json && $input.item.json.query) || {};
const got = q.secret || '';
if (!(expected && got && got === expected)) {
  return [];
}
return $input.all();

// 解析 Vikunja webhook 载荷，提取标签中的 fund:/res:/deliv:/milestone
const e = $input.item.json;
const evt = e.event_name;
const task = (e.data && e.data.task) ? e.data.task : {};
const labels = (task.labels || []).map(l => (l.title || l).toString());
function parseLabel(prefix){
  const m = labels.find(x => x.startsWith(prefix + ':'));
  return m ? m.slice(prefix.length + 1) : null;
}
const fund = parseLabel('fund');
if (!fund) return []; // 无 fund: 标签则不建账
let amount = null, currency = 'CNY', account = 'cash';
const parts = fund.split(':');
amount = parseFloat(parts[0]);
if (Number.isNaN(amount)) return []; // 标签格式错误 → 跳过，避免 NaN/¥0 建账
if (parts[1]) currency = parts[1];
if (parts[2]) account = parts[2];
return [{
  json: {
    event_name: evt,
    taskId: task.id,
    projectId: task.project_id,
    title: task.title,
    done: !!task.done,
    labels: labels,
    fund_amount: amount,
    fund_currency: currency,
    fund_account: account,
    is_recur: labels.includes('recur'),
    res: parseLabel('res'),
    deliv: parseLabel('deliv'),
    is_milestone: labels.includes('milestone')
  }
}];

