// P2 防重发护栏：若任务评论里已有「已自动记账」回执（含 #vk-<taskId>），说明本次/历史已完成真实记账，
// 跳过，避免编辑已完成任务、或取消完成后再完成导致重复记 type=3 真实支出。
const taskId = $json.taskId;
const auth = 'Bearer ' + $vars.vikunja_token;
const base = 'http://vikunja:3456/api/v1';
try {
  const resp = await this.helpers.httpRequest({ method:'GET', url: base + '/tasks/' + taskId + '/comments', headers:{Authorization:auth,'Content-Type':'application/json'}, json:true });
  const comments = Array.isArray(resp) ? resp : (resp.comments || []);
  const marker = '#vk-' + taskId;
  const already = comments.some(c => { const t = (c.comment || c.text || ''); return t.includes('已自动记账到 ezBookkeeping') || t.includes(marker); });
  return [{ json: { ...$json, alreadyAccounted: already } }];
} catch (e) {
  // 取评论失败：保守放行（仍记账），避免漏记真实支出；异常仅记录
  return [{ json: { ...$json, alreadyAccounted: false, commentCheckError: (e && e.message) ? e.message : String(e) } }];
}
